{"content": "import json
import re

ABHA_USER_NOT_FOUND = "ABDM-1114"
# The PHR address search answers an unknown address with these, not ABDM-1114
PHR_USER_NOT_FOUND = {"ABDM-1211", "ABDM-9999"}


def normalize_code(code) -> str | None:
    """ABDM codes may arrive as `ABDM-1001` or `ABDM-1001: `; compare on the code itself."""
    if code is None:
        return None
    return re.split(r"[:\s]", str(code).strip(), maxsplit=1)[0] or None


class AbdmError(Exception):
    """A call to ABDM was refused or could not be completed."""

    def __init__(
        self,
        message: str,
        *,
        status_code: int | None = None,
        code: str | None = None,
        fields: dict | None = None,
        request_id: str | None = None,
    ):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.code = normalize_code(code)
        self.fields = fields or {}
        self.request_id = request_id

    @property
    def is_upstream_failure(self) -> bool:
        return self.status_code is None or self.status_code >= 500  # noqa: PLR2004

    def is_user_not_found(self) -> bool:
        return self.code == ABHA_USER_NOT_FOUND

    def is_phr_user_not_found(self) -> bool:
        return self.code == ABHA_USER_NOT_FOUND or (
            self.code in PHR_USER_NOT_FOUND and "not found" in self.message.lower()
        )

    def as_dict(self) -> dict:
        return {
            "type": "abdm_error",
            "msg": self.message,
            "code": self.code,
            "fields": self.fields,
            "request_id": self.request_id,
        }

    @classmethod
    def from_response(cls, response, request_id: str | None = None) -> "AbdmError":
        status_code = response.status_code
        fallback = f"ABDM responded with HTTP {status_code}"
        if not response.content:
            return cls(fallback, status_code=status_code, request_id=request_id)
        try:
            body = response.json()
        except (json.JSONDecodeError, ValueError):
            return cls(fallback, status_code=status_code, request_id=request_id)

        if isinstance(body, dict) and isinstance(body.get("error"), dict):
            error = body["error"]
            return cls(
                error.get("message") or fallback,
                status_code=status_code,
                code=error.get("code"),
                request_id=request_id,
            )
        if isinstance(body, dict) and ("code" in body or "message" in body):
            return cls(
                body.get("message") or body.get("description") or fallback,
                status_code=status_code,
                code=body.get("code"),
                request_id=request_id,
            )
        if isinstance(body, dict):
            # Field level refusals: {"otpValue": "Invalid OTP value", "timestamp": ...}
            fields = {
                key: value
                for key, value in body.items()
                if key != "timestamp" and isinstance(value, str)
            }
            if fields:
                message = "; ".join(f"{key}: {value}" for key, value in fields.items())
                return cls(
                    message,
                    status_code=status_code,
                    fields=fields,
                    request_id=request_id,
                )
        return cls(fallback, status_code=status_code, request_id=request_id)


class AbdmConfigurationError(AbdmError):
    pass
