{"content": """"ABHA (M1) calls. Every sensitive value is encrypted here, in process, and never logged."""

from datetime import date, datetime

from django.conf import settings
from django.core.cache import cache

from care.abdm.service.client import abdm_request
from care.abdm.service.crypto import rsa_encrypt
from care.abdm.service.errors import AbdmError

CERTIFICATE_CACHE_KEY = "abdm:abha:certificate"
CERTIFICATE_CACHE_TTL = 60 * 60

ENROLMENT_CONSENT = {"code": "abha-enrollment", "version": "1.4"}

OTP_SYSTEM_SCOPES = {
    "aadhaar": "aadhaar-verify",
    "abdm": "mobile-verify",
}

GENDER_MAP = {
    "M": "male",
    "F": "female",
    "T": "transgender",
    "O": "non_binary",
}


def _url(path: str) -> str:
    return f"{settings.ABDM_ABHA_URL}{path}"


def _bearer(token: str) -> str:
    return f"Bearer {token}"


def get_certificate() -> dict:
    certificate = cache.get(CERTIFICATE_CACHE_KEY)
    if not certificate:
        data = abdm_request("GET", _url("/v3/profile/public/certificate")).json()
        certificate = {
            "public_key": data["publicKey"],
            "algorithm": data["encryptionAlgorithm"],
        }
        cache.set(CERTIFICATE_CACHE_KEY, certificate, timeout=CERTIFICATE_CACHE_TTL)
    return certificate


def encrypt(value: str) -> str:
    certificate = get_certificate()
    return rsa_encrypt(value, certificate["public_key"], certificate["algorithm"])


def _otp_auth(txn_id: str, otp: str, **extra) -> dict:
    return {
        "authMethods": ["otp"],
        "otp": {"txnId": txn_id, "otpValue": encrypt(otp), **extra},
    }


def _ensure_auth_success(data: dict):
    # PHR verification answers a wrong or expired OTP with 200 and authResult failed
    result = data.get("authResult")
    if result and result.lower() != "success":
        raise AbdmError(
            data.get("message") or "OTP verification failed", status_code=422
        )


def format_abha_number(value: str) -> str:
    digits = "".join(ch for ch in value if ch.isdigit())
    if len(digits) != 14:  # noqa: PLR2004
        return value
    return f"{digits[:2]}-{digits[2:6]}-{digits[6:10]}-{digits[10:]}"


def qualify_abha_address(value: str) -> str:
    value = value.strip()
    return value if "@" in value else f"{value}@{settings.ABDM_CM_ID}"


# Enrolment, by Aadhaar OTP


def enrol_request_aadhaar_otp(aadhaar: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/enrollment/request/otp"),
        json={
            "txnId": "",
            "scope": ["abha-enrol"],
            "loginHint": "aadhaar",
            "loginId": encrypt(aadhaar),
            "otpSystem": "aadhaar",
        },
    ).json()


def enrol_by_aadhaar(txn_id: str, otp: str, mobile: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/enrollment/enrol/byAadhaar"),
        json={
            "authData": _otp_auth(txn_id, otp, mobile=mobile),
            "consent": ENROLMENT_CONSENT,
        },
    ).json()


def enrol_request_mobile_otp(txn_id: str, mobile: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/enrollment/request/otp"),
        json={
            "txnId": txn_id,
            "scope": ["abha-enrol", "mobile-verify"],
            "loginHint": "mobile",
            "loginId": encrypt(mobile),
            "otpSystem": "abdm",
        },
    ).json()


def enrol_verify_mobile_otp(txn_id: str, otp: str) -> dict:
    data = abdm_request(
        "POST",
        _url("/v3/enrollment/auth/byAbdm"),
        json={
            "scope": ["abha-enrol", "mobile-verify"],
            "authData": _otp_auth(txn_id, otp),
        },
    ).json()
    _ensure_auth_success(data)
    return data


def enrol_address_suggestions(txn_id: str) -> dict:
    return abdm_request(
        "GET",
        _url("/v3/enrollment/enrol/suggestion"),
        headers={"TRANSACTION_ID": txn_id},
    ).json()


def enrol_set_address(txn_id: str, abha_address: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/enrollment/enrol/abha-address"),
        json={"txnId": txn_id, "abhaAddress": abha_address, "preferred": 1},
    ).json()


# Login by mobile, Aadhaar or ABHA number


def login_request_otp(login_hint: str, login_id: str, otp_system: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/profile/login/request/otp"),
        json={
            "scope": ["abha-login", OTP_SYSTEM_SCOPES[otp_system]],
            "loginHint": login_hint,
            "loginId": encrypt(login_id),
            "otpSystem": otp_system,
        },
    ).json()


def login_verify_otp(txn_id: str, otp: str, otp_system: str) -> dict:
    data = abdm_request(
        "POST",
        _url("/v3/profile/login/verify"),
        json={
            "scope": ["abha-login", OTP_SYSTEM_SCOPES[otp_system]],
            "authData": _otp_auth(txn_id, otp),
        },
    ).json()
    _ensure_auth_success(data)
    return data


def login_verify_user(txn_id: str, abha_number: str, t_token: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/profile/login/verify/user"),
        headers={"T-token": _bearer(t_token)},
        json={"ABHANumber": abha_number, "txnId": txn_id},
    ).json()


# Login by ABHA address, through the PHR login family


def phr_search(abha_address: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/phr/web/login/abha/search"),
        json={"abhaAddress": abha_address},
    ).json()


def phr_request_otp(abha_address: str, otp_system: str) -> dict:
    return abdm_request(
        "POST",
        _url("/v3/phr/web/login/abha/request/otp"),
        json={
            "scope": ["abha-address-login", OTP_SYSTEM_SCOPES[otp_system]],
            "loginHint": "abha-address",
            "loginId": encrypt(abha_address),
            "otpSystem": otp_system,
        },
    ).json()


def phr_verify_otp(txn_id: str, otp: str, otp_system: str) -> dict:
    data = abdm_request(
        "POST",
        _url("/v3/phr/web/login/abha/verify"),
        json={
            "scope": ["abha-address-login", OTP_SYSTEM_SCOPES[otp_system]],
            "authData": _otp_auth(txn_id, otp),
        },
    ).json()
    _ensure_auth_success(data)
    return data


# Profile, with the user token in X-token


def get_profile(x_token: str) -> dict:
    return abdm_request(
        "GET",
        _url("/v3/profile/account"),
        headers={"X-token": _bearer(x_token)},
    ).json()


def get_phr_profile(x_token: str) -> dict:
    return abdm_request(
        "GET",
        _url("/v3/phr/web/login/profile/abha-profile"),
        headers={"X-token": _bearer(x_token)},
    ).json()


def get_card(x_token: str, *, phr: bool = False, download: bool = False):
    if phr:
        path = "/v3/phr/web/login/profile/abha/phr-card"
    elif download:
        path = "/v3/profile/account/download-abha-card"
    else:
        path = "/v3/profile/account/abha-card"
    response = abdm_request("GET", _url(path), headers={"X-token": _bearer(x_token)})
    return response.content, response.headers.get("Content-Type", "image/png")


def refresh_user_token(refresh_token: str) -> dict:
    return abdm_request(
        "GET",
        _url("/v3/profile/account/request/token"),
        headers={"R-token": _bearer(refresh_token)},
    ).json()


# Normalising the several profile shapes ABDM returns into one


def _parse_date(value) -> date | None:
    if not value or not isinstance(value, str):
        return None
    for fmt in ("%d-%m-%Y", "%Y-%m-%d", "%d/%m/%Y"):
        try:
            return datetime.strptime(value, fmt).date()  # noqa: DTZ007
        except ValueError:
            continue
    return None


def _date_from_parts(profile: dict) -> date | None:
    try:
        return date(
            int(profile["yearOfBirth"]),
            int(profile["monthOfBirth"]),
            int(profile["dayOfBirth"]),
        )
    except (KeyError, TypeError, ValueError):
        return None


def _year(profile: dict, dob: date | None) -> int | None:
    if dob:
        return dob.year
    try:
        return int(profile.get("yearOfBirth"))
    except (TypeError, ValueError):
        return None


def normalize_profile(profile: dict) -> dict:
    """Maps the enrolment, account, login and PHR profile shapes onto one set of fields."""
    first = (profile.get("firstName") or "").strip()
    middle = (profile.get("middleName") or "").strip()
    last = (profile.get("lastName") or "").strip()
    name = (
        profile.get("name")
        or profile.get("fullName")
        or " ".join(part for part in (first, middle, last) if part)
    )
    addresses = profile.get("phrAddress") or []
    abha_address = (
        profile.get("preferredAbhaAddress")
        or profile.get("abhaAddress")
        or profile.get("healthId")
        or (addresses[0] if addresses else None)
    )
    dob = (
        _date_from_parts(profile)
        or _parse_date(profile.get("dob"))
        or _parse_date(profile.get("dateOfBirth"))
    )
    kyc = profile.get("kycVerified")
    if kyc is None and profile.get("kycStatus"):
        kyc = str(profile["kycStatus"]).upper() == "VERIFIED"
    return {
        "abha_number": profile.get("ABHANumber")
        or profile.get("abhaNumber")
        or profile.get("healthIdNumber"),
        "abha_address": abha_address,
        "name": name or "",
        "first_name": first,
        "middle_name": middle,
        "last_name": last,
        "gender": GENDER_MAP.get(str(profile.get("gender") or "").upper(), ""),
        "date_of_birth": dob,
        "year_of_birth": _year(profile, dob),
        "mobile": profile.get("mobile") or "",
        "email": profile.get("email") or "",
        "address": profile.get("address") or "",
        "pincode": profile.get("pincode") or profile.get("pinCode") or "",
        "state_code": profile.get("stateCode") or "",
        "state_name": profile.get("stateName") or "",
        "district_code": profile.get("districtCode") or "",
        "district_name": profile.get("districtName") or "",
        "kyc_verified": bool(kyc),
        "status": profile.get("status") or profile.get("abhaStatus") or "",
        "profile_photo": profile.get("profilePhoto")
        or profile.get("photo")
        or profile.get("kycPhoto")
        or "",
    }


def normalize_account(account: dict) -> dict:
    """An entry of the `accounts` or `users` array on a login verification."""
    return {
        "abha_number": account.get("ABHANumber") or account.get("abhaNumber"),
        "abha_address": account.get("preferredAbhaAddress")
        or account.get("abhaAddress"),
        "name": account.get("name") or account.get("fullName") or "",
        "gender": GENDER_MAP.get(str(account.get("gender") or "").upper(), ""),
        "kyc_verified": bool(
            account.get("kycVerified")
            or str(account.get("kycStatus") or "").upper() == "VERIFIED"
        ),
        "status": account.get("status") or "",
        "profile_photo": account.get("profilePhoto") or "",
    }
