{"content": "from django.db import transaction
from rest_framework.exceptions import ValidationError

from care.abdm.models import AbhaNumber
from care.emr.models.patient import Patient, PatientIdentifier
from care.emr.resources.patient_identifier.spec import PatientIdentifierStatus
from care.emr.signals.patient.base import BasePatientIdentifierConfig


class AbhaNumberIdentifierConfig(BasePatientIdentifierConfig):
    IDENTIFIER_SYSTEM = "system.care.ohc.network/abha-number"
    CACHED_CONFIG = {}
    DISPLAY = "ABHA Number"
    RETRIEVE_WITH_YOB = False
    PARTIAL_SEARCH = False


class AbhaAddressIdentifierConfig(BasePatientIdentifierConfig):
    IDENTIFIER_SYSTEM = "system.care.ohc.network/abha-address"
    CACHED_CONFIG = {}
    DISPLAY = "ABHA Address"
    RETRIEVE_WITH_YOB = False
    PARTIAL_SEARCH = False


def sync_abha_identifiers(patient: Patient):
    """Mirrors the linked ABHA onto the patient's auto maintained instance identifiers."""
    abha = AbhaNumber.objects.filter(patient=patient).first()
    for config_class, value in (
        (AbhaNumberIdentifierConfig, abha and abha.abha_number),
        (AbhaAddressIdentifierConfig, abha and abha.abha_address),
    ):
        config = config_class.get_or_create_system_name_identifier_config(None)
        if config.status != PatientIdentifierStatus.active.value:
            continue
        if value:
            PatientIdentifier.objects.update_or_create(
                patient=patient, config=config, defaults={"value": value}
            )
        else:
            PatientIdentifier.objects.filter(patient=patient, config=config).delete()
    patient.build_instance_identifiers()
    Patient.objects.filter(id=patient.id).update(
        instance_identifiers=patient.instance_identifiers
    )


def link_abha_to_patient(abha: AbhaNumber, patient: Patient, user) -> AbhaNumber:
    """One ABHA maps to one patient, and one patient holds one ABHA."""
    with transaction.atomic():
        abha = AbhaNumber.objects.select_for_update().get(id=abha.id)
        if abha.patient_id == patient.id:
            return abha
        if abha.patient_id:
            msg = f"This ABHA is already linked to patient {abha.patient.external_id}"
            raise ValidationError(msg)
        existing = AbhaNumber.objects.filter(patient=patient).first()
        if existing:
            msg = f"This patient is already linked to ABHA {existing}"
            raise ValidationError(msg)
        abha.patient = patient
        abha.updated_by = user
        abha.save(update_fields=["patient", "updated_by", "modified_date"])
        sync_abha_identifiers(patient)
    return abha
