from datetime import date, datetime

from pydantic import UUID4, BaseModel, Field, field_validator

from care.abdm.models import AbhaNumber
from care.emr.resources.base import EMRResource

AADHAAR_REGEX = r"^\d{12}$"
MOBILE_REGEX = r"^[6-9]\d{9}$"
OTP_REGEX = r"^\d{6}$"
# 14 digits, with or without the dashes ABDM prints them with
ABHA_NUMBER_REGEX = r"^\d{2}-?\d{4}-?\d{4}-?\d{4}$"
# ABHA address rules from the enrolment screen: 8 to 18 characters, letters and
# digits, at most one dot and one underscore, neither first nor last
ABHA_ADDRESS_REGEX = r"^(?!.*\..*\.)(?!.*_.*_)[a-zA-Z0-9][a-zA-Z0-9._]{6,16}[a-zA-Z0-9]$"


class AbhaPatientSpec(BaseModel):
    id: UUID4
    name: str


class AbhaNumberSpec(EMRResource):
    __model__ = AbhaNumber

    id: UUID4 | None = None
    abha_number: str | None = None
    abha_address: str | None = None
    name: str
    first_name: str
    middle_name: str
    last_name: str
    gender: str
    date_of_birth: date | None = None
    year_of_birth: int | None = None
    mobile: str
    email: str
    address: str
    pincode: str
    state_code: str
    state_name: str
    district_code: str
    district_name: str
    kyc_verified: bool
    status: str
    profile_photo: str
    token_kind: str
    patient: AbhaPatientSpec | None = None
    created_date: datetime | None = None
