{"content": "import logging

from django.conf import settings
from django.http import HttpResponse
from django.utils import timezone
from drf_spectacular.utils import extend_schema
from rest_framework.decorators import action
from rest_framework.exceptions import NotFound, PermissionDenied, ValidationError
from rest_framework.response import Response
from rest_framework.viewsets import GenericViewSet

from care.abdm.identifiers import link_abha_to_patient
from care.abdm.models import AbhaNumber, AbhaTokenKind
from care.abdm.resources import (
    AbhaNumberSpec,
    EnrolSendAadhaarOtpRequest,
    EnrolSendMobileOtpRequest,
    EnrolSetAddressRequest,
    EnrolVerifyAadhaarOtpRequest,
    LinkPatientRequest,
    LoginSendOtpRequest,
    SelectAccountRequest,
    TxnRequest,
    VerifyOtpRequest,
)
from care.abdm.service import abha as abha_service
from care.abdm.service import transactions
from care.abdm.service.accounts import get_user_token, save_account
from care.abdm.service.errors import AbdmError
from care.emr.api.viewsets.base import (
    EMRBaseViewSet,
    EMRListMixin,
    EMRRetrieveMixin,
    emr_exception_handler,
)
from care.emr.models.patient import Patient
from care.security.authorization import AuthorizationController
from care.utils.shortcuts import get_object_or_404

logger = logging.getLogger(__name__)

LOGIN_HINTS = {"mobile": "mobile", "aadhaar": "aadhaar", "abha_number": "abha-number"}
PHR_AUTH_METHODS = {"aadhaar": "AADHAAR_OTP", "abdm": "MOBILE_OTP"}


def abdm_exception_handler(exc, context):
    if isinstance(exc, AbdmError):
        logger.warning(
            "ABDM call refused: code=%s status=%s request_id=%s",
            exc.code,
            exc.status_code,
            exc.request_id,
        )
        # ABDM's own 401s must not reach the browser as ours, which would end the session
        status = 502 if exc.is_upstream_failure else 400
        return Response({"errors": [exc.as_dict()], "detail": exc.message}, status)
    return emr_exception_handler(exc, context)


class AbdmViewSetMixin:
    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if not settings.ABDM_ENABLED:
            msg = "ABDM integration is not enabled"
            raise NotFound(msg)

    def authorize_desk(self):
        user = self.request.user
        if not (
            user.is_superuser
            or AuthorizationController.call("can_create_patient", user)
        ):
            msg = "You do not have permission to register patients"
            raise PermissionDenied(msg)


def linked_patients(abha_numbers: list[str]) -> dict:
    numbers = [abha_service.format_abha_number(n) for n in abha_numbers if n]
    return {
        account.abha_number: {"id": account.patient.external_id, "name": account.patient.name}
        for account in AbhaNumber.objects.filter(
            abha_number__in=numbers, patient__isnull=False
        ).select_related("patient")
    }


def found_response(account: AbhaNumber, **extra) -> Response:
    return Response(
        {
            "status": "found",
            "abha_number": AbhaNumberSpec.serialize(account).to_json(),
            **extra,
        }
    )


def not_found_response(message: str) -> Response:
    return Response({"status": "not_found", "message": message})


class AbhaLoginViewSet(AbdmViewSetMixin, GenericViewSet):
    """Every identifier, Aadhaar included, starts here so nobody is enrolled twice."""

    @extend_schema(request=LoginSendOtpRequest)
    @action(detail=False, methods=["POST"])
    def send_otp(self, request):
        self.authorize_desk()
        req = LoginSendOtpRequest.model_validate(request.data)

        if req.identifier == "abha_address":
            address = abha_service.qualify_abha_address(req.value)
            try:
                search = abha_service.phr_search(address)
            except AbdmError as e:
                if e.is_phr_user_not_found():
                    return not_found_response("No ABHA is registered with this address")
                raise
            auth_methods = search.get("authMethods") or []
            if auth_methods and PHR_AUTH_METHODS[req.otp_system] not in auth_methods:
                msg = "This ABHA address cannot be verified by the chosen OTP method"
                raise ValidationError(msg)
            data = abha_service.phr_request_otp(address, req.otp_system)
            flow = "phr_login"
        else:
            value = (
                abha_service.format_abha_number(req.value)
                if req.identifier == "abha_number"
                else req.value
            )
            try:
                data = abha_service.login_request_otp(
                    LOGIN_HINTS[req.identifier], value, req.otp_system
                )
            except AbdmError as e:
                if e.is_user_not_found():
                    return not_found_response("No ABHA is linked to this identifier")
                raise
            flow = "login"

        txn_id = data["txnId"]
        transactions.start(
            txn_id,
            request.user,
            flow=flow,
            identifier=req.identifier,
            otp_system=req.otp_system,
        )
        return Response(
            {"status": "otp_sent", "txn_id": txn_id, "message": data.get("message", "")}
        )

    def _complete_login(self, tokens: dict) -> AbhaNumber:
        profile = abha_service.normalize_profile(
            abha_service.get_profile(tokens["token"])
        )
        return save_account(profile, tokens, self.request.user)

    @extend_schema(request=VerifyOtpRequest)
    @action(detail=False, methods=["POST"])
    def verify_otp(self, request):
        self.authorize_desk()
        req = VerifyOtpRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "login", "phr_login")

        if state["flow"] == "phr_login":
            data = abha_service.phr_verify_otp(req.txn_id, req.otp, state["otp_system"])
            tokens = data.get("tokens") or {}
            if not tokens.get("token"):
                raise AbdmError(data.get("message") or "Verification failed", status_code=422)
            profile = abha_service.normalize_profile(
                abha_service.get_phr_profile(tokens["token"])
            )
            account = save_account(profile, tokens, request.user, AbhaTokenKind.phr)
            transactions.end(req.txn_id)
            return found_response(account)

        try:
            data = abha_service.login_verify_otp(req.txn_id, req.otp, state["otp_system"])
        except AbdmError as e:
            if e.is_user_not_found():
                transactions.end(req.txn_id)
                return not_found_response("No ABHA is linked to this identifier")
            raise

        # A refreshToken means this is already the user token; read the token, not the account count
        if data.get("refreshToken"):
            account = self._complete_login(data)
            transactions.end(req.txn_id)
            return found_response(account)

        accounts = [abha_service.normalize_account(a) for a in data.get("accounts") or []]
        if not accounts:
            transactions.end(req.txn_id)
            return not_found_response("No ABHA is linked to this identifier")

        txn_id = transactions.update(
            req.txn_id,
            state,
            data.get("txnId"),
            t_token=data.get("token"),
            accounts=[a["abha_number"] for a in accounts if a["abha_number"]],
        )
        linked = linked_patients([a["abha_number"] for a in accounts])
        for account in accounts:
            account["patient"] = linked.get(
                abha_service.format_abha_number(account["abha_number"] or "")
            )
        return Response(
            {"status": "select_account", "txn_id": txn_id, "accounts": accounts}
        )

    @extend_schema(request=SelectAccountRequest)
    @action(detail=False, methods=["POST"])
    def select_account(self, request):
        self.authorize_desk()
        req = SelectAccountRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "login")
        abha_number = abha_service.format_abha_number(req.abha_number)
        offered = [abha_service.format_abha_number(n) for n in state.get("accounts", [])]
        if not state.get("t_token") or abha_number not in offered:
            msg = "Choose one of the ABHA accounts offered for this verification"
            raise ValidationError(msg)
        data = abha_service.login_verify_user(req.txn_id, abha_number, state["t_token"])
        account = self._complete_login(data)
        transactions.end(req.txn_id)
        return found_response(account)


class AbhaEnrolViewSet(AbdmViewSetMixin, GenericViewSet):
    """ABHA creation by Aadhaar OTP, the only creation route offered at the desk."""

    @extend_schema(request=EnrolSendAadhaarOtpRequest)
    @action(detail=False, methods=["POST"])
    def send_aadhaar_otp(self, request):
        self.authorize_desk()
        req = EnrolSendAadhaarOtpRequest.model_validate(request.data)
        data = abha_service.enrol_request_aadhaar_otp(req.aadhaar)
        txn_id = data["txnId"]
        transactions.start(
            txn_id,
            request.user,
            flow="enrol",
            consent={
                "code": req.consent.code,
                "version": req.consent.version,
                "agreed_at": timezone.now().isoformat(),
                "recorded_by": str(request.user.external_id),
            },
        )
        return Response({"txn_id": txn_id, "message": data.get("message", "")})

    @extend_schema(request=EnrolVerifyAadhaarOtpRequest)
    @action(detail=False, methods=["POST"])
    def verify_aadhaar_otp(self, request):
        self.authorize_desk()
        req = EnrolVerifyAadhaarOtpRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "enrol")
        data = abha_service.enrol_by_aadhaar(req.txn_id, req.otp, req.mobile)

        profile = abha_service.normalize_profile(data.get("ABHAProfile") or {})
        account = save_account(
            profile,
            data.get("tokens"),
            request.user,
            enrolment_consent=state["consent"],
        )
        abha_mobile = profile.get("mobile") or ""
        mobile_verification_required = abha_mobile[-4:] != req.mobile[-4:]
        txn_id = transactions.update(
            req.txn_id,
            state,
            data.get("txnId"),
            abha_number_id=account.id,
            mobile=req.mobile,
        )
        return Response(
            {
                "txn_id": txn_id,
                "is_new": bool(data.get("isNew")),
                "message": data.get("message", ""),
                "mobile_verification_required": mobile_verification_required,
                "abha_number": AbhaNumberSpec.serialize(account).to_json(),
            }
        )

    @extend_schema(request=EnrolSendMobileOtpRequest)
    @action(detail=False, methods=["POST"])
    def send_mobile_otp(self, request):
        self.authorize_desk()
        req = EnrolSendMobileOtpRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "enrol")
        data = abha_service.enrol_request_mobile_otp(req.txn_id, req.mobile)
        txn_id = transactions.update(
            req.txn_id, state, data.get("txnId"), mobile=req.mobile
        )
        return Response({"txn_id": txn_id, "message": data.get("message", "")})

    @extend_schema(request=VerifyOtpRequest)
    @action(detail=False, methods=["POST"])
    def verify_mobile_otp(self, request):
        self.authorize_desk()
        req = VerifyOtpRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "enrol")
        data = abha_service.enrol_verify_mobile_otp(req.txn_id, req.otp)
        txn_id = transactions.update(req.txn_id, state, data.get("txnId"))
        AbhaNumber.objects.filter(id=state.get("abha_number_id")).update(
            mobile=state.get("mobile", "")
        )
        return Response({"txn_id": txn_id, "message": data.get("message", "")})

    @extend_schema(request=TxnRequest)
    @action(detail=False, methods=["POST"])
    def address_suggestions(self, request):
        self.authorize_desk()
        req = TxnRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "enrol")
        data = abha_service.enrol_address_suggestions(req.txn_id)
        txn_id = transactions.update(req.txn_id, state, data.get("txnId"))
        return Response(
            {"txn_id": txn_id, "suggestions": data.get("abhaAddressList") or []}
        )

    @extend_schema(request=EnrolSetAddressRequest)
    @action(detail=False, methods=["POST"])
    def set_address(self, request):
        self.authorize_desk()
        req = EnrolSetAddressRequest.model_validate(request.data)
        state = transactions.get(req.txn_id, request.user, "enrol")
        data = abha_service.enrol_set_address(req.txn_id, req.abha_address)

        account = get_object_or_404(AbhaNumber, id=state.get("abha_number_id"))
        account.abha_address = data.get("preferredAbhaAddress") or account.abha_address
        account.save(update_fields=["abha_address", "modified_date"])
        try:
            profile = abha_service.normalize_profile(
                abha_service.get_profile(get_user_token(account))
            )
            account = save_account(profile, None, request.user)
        except AbdmError as e:
            # The address exists either way; a stale local copy is refreshed on the next login
            logger.warning("ABDM profile refresh after enrolment failed: %s", e.message)
        if account.patient_id:
            from care.abdm.identifiers import sync_abha_identifiers

            sync_abha_identifiers(account.patient)
        transactions.end(req.txn_id)
        return Response({"abha_number": AbhaNumberSpec.serialize(account).to_json()})


class AbhaNumberViewSet(
    AbdmViewSetMixin, EMRRetrieveMixin, EMRListMixin, EMRBaseViewSet
):
    database_model = AbhaNumber
    pydantic_model = AbhaNumberSpec

    def get_queryset(self):
        queryset = AbhaNumber.objects.select_related("patient").order_by("-id")
        if self.action != "list":
            return queryset
        if patient_id := self.request.GET.get("patient"):
            patient = get_object_or_404(Patient, external_id=patient_id)
            self.authorize_patient_view(patient)
            return queryset.filter(patient=patient)
        if self.request.user.is_superuser:
            return queryset
        return queryset.filter(created_by=self.request.user, patient__isnull=True)

    def authorize_patient_view(self, patient):
        if not AuthorizationController.call(
            "can_view_patient_obj", self.request.user, patient
        ):
            msg = "You do not have permission to view this patient"
            raise PermissionDenied(msg)

    def authorize_retrieve(self, model_instance):
        if model_instance.patient:
            self.authorize_patient_view(model_instance.patient)
        elif not (
            self.request.user.is_superuser
            or model_instance.created_by_id == self.request.user.id
        ):
            msg = "You do not have permission to view this ABHA"
            raise PermissionDenied(msg)

    @action(detail=True, methods=["GET"])
    def card(self, request, *args, **kwargs):
        account = self.get_object()
        self.authorize_retrieve(account)
        kind = request.GET.get("kind", "card")
        content, content_type = abha_service.get_card(
            get_user_token(account), account.token_kind, kind
        )
        response = HttpResponse(content, content_type=content_type)
        if kind == "pdf":
            response["Content-Disposition"] = f'attachment; filename="abha-{account}.pdf"'
        return response

    @extend_schema(request=LinkPatientRequest, responses={200: AbhaNumberSpec})
    @action(detail=True, methods=["POST"])
    def link_patient(self, request, *args, **kwargs):
        req = LinkPatientRequest.model_validate(request.data)
        account = self.get_object()
        self.authorize_retrieve(account)
        patient = get_object_or_404(Patient, external_id=req.patient)
        if not AuthorizationController.call(
            "can_write_patient_obj", request.user, patient
        ):
            msg = "You do not have permission to update this patient"
            raise PermissionDenied(msg)
