{"content": "from unittest.mock import patch

from django.test import override_settings
from django.urls import reverse

from care.abdm.identifiers import AbhaAddressIdentifierConfig, AbhaNumberIdentifierConfig
from care.abdm.models import AbhaNumber
from care.abdm.service.errors import AbdmError
from care.abdm.tests.test_service import LOCMEM_CACHE
from care.emr.models.patient import PatientIdentifier
from care.utils.tests.base import CareAPITestBase

ABHA = "care.abdm.service.abha"

PROFILE = {
    "ABHANumber": "91-1111-2222-3333",
    "preferredAbhaAddress": "jane.doe@sbx",
    "name": "Jane Doe",
    "firstName": "Jane",
    "lastName": "Doe",
    "gender": "F",
    "yearOfBirth": "1990",
    "monthOfBirth": "4",
    "dayOfBirth": "12",
    "mobile": "******3210",
    "kycVerified": True,
}
TOKENS = {
    "token": "x-token",
    "expiresIn": 1800,
    "refreshToken": "r-token",
    "refreshExpiresIn": 1296000,
}


def not_found():
    return AbdmError("User not found.", status_code=404, code="ABDM-1114")


@override_settings(CACHES=LOCMEM_CACHE, ABDM_ENABLED=True)
class AbdmApiTestBase(CareAPITestBase):
    def setUp(self):
        super().setUp()
        AbhaNumberIdentifierConfig.CACHED_CONFIG = {}
        AbhaAddressIdentifierConfig.CACHED_CONFIG = {}
        self.user = self.create_super_user()
        self.client.force_authenticate(self.user)

    def url(self, name):
        return reverse(name)


class AbhaLoginTests(AbdmApiTestBase):
    def send_otp(self, **data):
        return self.client.post(
            self.url("abdm-abha-login-send-otp"), data, format="json"
        )

    @patch(f"{ABHA}.login_request_otp")
    def test_invalid_aadhaar_is_refused_before_any_call(self, request_otp):
        for value in ("12345678901", "1234567890123"):
            response = self.send_otp(
                identifier="aadhaar", value=value, otp_system="aadhaar"
            )
            self.assertEqual(response.status_code, 400)
        request_otp.assert_not_called()

    @patch(f"{ABHA}.login_request_otp", side_effect=not_found())
    def test_unknown_identifier_is_not_found(self, _):
        response = self.send_otp(identifier="abha_number", value="91-0000-0000-0007")
        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.json()["status"], "not_found")

    @patch(f"{ABHA}.get_profile", return_value=PROFILE)
    @patch(f"{ABHA}.login_verify_user")
    @patch(f"{ABHA}.login_verify_otp")
    @patch(f"{ABHA}.login_request_otp")
    def test_aadhaar_login_uses_the_token_without_an_exchange(
        self, request_otp, verify_otp, verify_user, _
    ):
        request_otp.return_value = {"txnId": "txn-1", "message": "OTP sent to ****3210"}
        verify_otp.return_value = {
            "txnId": "txn-1",
            "authResult": "success",
            **TOKENS,
            "accounts": [{"ABHANumber": "91-1111-2222-3333"}],
        }
        self.send_otp(identifier="aadhaar", value="123456789012", otp_system="aadhaar")
        response = self.client.post(
            self.url("abdm-abha-login-verify-otp"),
            {"txn_id": "txn-1", "otp": "123456"},
            format="json",
        )
        self.assertEqual(response.status_code, 200)
        body = response.json()
        self.assertEqual(body["status"], "found")
        self.assertEqual(body["abha_number"]["abha_number"], "91-1111-2222-3333")
        self.assertEqual(body["abha_number"]["gender"], "female")
        self.assertNotIn("access_token", body["abha_number"])
        verify_user.assert_not_called()
        self.assertEqual(AbhaNumber.objects.get().access_token, "x-token")

    @patch(f"{ABHA}.get_profile", return_value=PROFILE)
    @patch(f"{ABHA}.login_verify_user", return_value=TOKENS)
    @patch(f"{ABHA}.login_verify_otp")
    @patch(f"{ABHA}.login_request_otp")
    def test_mobile_login_with_several_accounts(
        self, request_otp, verify_otp, verify_user, _
    ):
        request_otp.return_value = {"txnId": "txn-2", "message": "sent"}
        verify_otp.return_value = {
            "txnId": "txn-2",
            "authResult": "success",
            "token": "t-token",
            "accounts": [
                {"ABHANumber": "91-1111-2222-3333", "name": "Jane"},
                {"ABHANumber": "91-4444-5555-6666", "name": "John"},
            ],
        }
        linked_patient = self.create_patient(name="John")
        AbhaNumber.objects.create(abha_number="91-4444-5555-6666", patient=linked_patient)

        self.send_otp(identifier="mobile", value="9876543210")
        response = self.client.post(
            self.url("abdm-abha-login-verify-otp"),
            {"txn_id": "txn-2", "otp": "123456"},
            format="json",
        )
        body = response.json()
        self.assertEqual(body["status"], "select_account")
        self.assertEqual(len(body["accounts"]), 2)
        self.assertIsNone(body["accounts"][0]["patient"])
        self.assertEqual(body["accounts"][1]["patient"]["id"], str(linked_patient.external_id))

        response = self.client.post(
            self.url("abdm-abha-login-select-account"),
            {"txn_id": "txn-2", "abha_number": "91-9999-9999-9999"},
            format="json",
        )
        self.assertEqual(response.status_code, 400)

        response = self.client.post(
            self.url("abdm-abha-login-select-account"),
            {"txn_id": "txn-2", "abha_number": "91-1111-2222-3333"},
            format="json",
        )
        self.assertEqual(response.json()["status"], "found")
        verify_user.assert_called_once_with("txn-2", "91-1111-2222-3333", "t-token")

    @patch(f"{ABHA}.login_verify_otp", side_effect=not_found())
    @patch(f"{ABHA}.login_request_otp", return_value={"txnId": "txn-3"})
    def test_no_abha_on_mobile_is_not_found(self, *_):
        self.send_otp(identifier="mobile", value="9876543210")
        response = self.client.post(
            self.url("abdm-abha-login-verify-otp"),
            {"txn_id": "txn-3", "otp": "123456"},
            format="json",
        )
        self.assertEqual(response.json()["status"], "not_found")

    @patch(f"{ABHA}.login_request_otp", return_value={"txnId": "txn-4"})
    def test_transaction_is_bound_to_its_user(self, _):
        self.send_otp(identifier="mobile", value="9876543210")
        self.client.force_authenticate(self.create_super_user())
        response = self.client.post(
            self.url("abdm-abha-login-verify-otp"),
            {"txn_id": "txn-4", "otp": "123456"},
            format="json",
        )
        self.assertEqual(response.status_code, 400)

    @patch(f"{ABHA}.login_verify_otp")
    @patch(f"{ABHA}.login_request_otp", return_value={"txnId": "txn-5"})
    def test_wrong_otp_is_a_bad_request_not_a_logout(self, _, verify_otp):
        verify_otp.side_effect = AbdmError(
            "otpValue: Invalid OTP value", status_code=401, fields={"otpValue": "x"}
        )
        self.send_otp(identifier="mobile", value="9876543210")
        response = self.client.post(
            self.url("abdm-abha-login-verify-otp"),
            {"txn_id": "txn-5", "otp": "123456"},
            format="json",
        )
        self.assertEqual(response.status_code, 400)
        self.assertEqual(response.json()["errors"][0]["type"], "abdm_error")

    @patch(f"{ABHA}.get_phr_profile")
    @patch(f"{ABHA}.phr_verify_otp")
    @patch(f"{ABHA}.phr_request_otp", return_value={"txnId": "txn-6"})
    @patch(f"{ABHA}.phr_search")
    def test_abha_address_login(self, search, request_otp, verify_otp, phr_profile):
        search.return_value = {"authMethods": ["MOBILE_OTP"]}
        verify_otp.return_value = {"authResult": "success", "tokens": TOKENS}
        phr_profile.return_value = {
            "abhaAddress": "jane.doe@sbx",
            "abhaNumber": "91-1111-2222-3333",
            "fullName": "Jane Doe",
            "kycStatus": "VERIFIED",
        }
        self.send_otp(identifier="abha_address", value="jane.doe")
        search.assert_called_once_with("jane.doe@sbx")
        response = self.client.post(
            self.url("abdm-abha-login-verify-otp"),
            {"txn_id": "txn-6", "otp": "123456"},
            format="json",
        )
        body = response.json()
        self.assertEqual(body["status"], "found")
        self.assertEqual(body["abha_number"]["token_kind"], "phr")
        self.assertTrue(body["abha_number"]["kyc_verified"])

    @patch(f"{ABHA}.login_request_otp")
    def test_requires_patient_create_permission(self, request_otp):
        self.client.force_authenticate(self.create_user())
        response = self.send_otp(identifier="mobile", value="9876543210")
        self.assertEqual(response.status_code, 403)
        request_otp.assert_not_called()

    @override_settings(ABDM_ENABLED=False)
    def test_disabled(self):
        response = self.send_otp(identifier="mobile", value="9876543210")
        self.assertEqual(response.status_code, 404)


class AbhaEnrolTests(AbdmApiTestBase):
    @patch(f"{ABHA}.enrol_request_aadhaar_otp")
    def test_consent_is_required(self, request_otp):
