            self.url("abdm-abha-enrol-send-aadhaar-otp"),
            {
                "aadhaar": "123456789012",
                "consent": {"code": "abha-enrollment", "version": "1.4", "agreed": False},
            },
            format="json",
        )
        self.assertEqual(response.status_code, 400)
        request_otp.assert_not_called()

    @patch(f"{ABHA}.get_profile", return_value=PROFILE)
    @patch(f"{ABHA}.enrol_set_address")
    @patch(f"{ABHA}.enrol_address_suggestions")
    @patch(f"{ABHA}.enrol_by_aadhaar")
    @patch(f"{ABHA}.enrol_request_aadhaar_otp")
    def test_create_by_aadhaar_otp(
