class AbhaNumberTests(AbdmApiTestBase):
    def setUp(self):
        super().setUp()
        self.account = AbhaNumber.objects.create(
            abha_number="91-1111-2222-3333",
            abha_address="jane.doe@sbx",
            access_token="x-token",
            created_by=self.user,
        )

    def link(self, account, patient):
        return self.client.post(
            reverse("abdm-abha-number-link-patient", args=[account.external_id]),
            {"patient": str(patient.external_id)},
            format="json",
        )

    def test_link_patient_sets_identifiers(self):
        patient = self.create_patient()
        response = self.link(self.account, patient)
        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.json()["patient"]["id"], str(patient.external_id))
        values = set(
            PatientIdentifier.objects.filter(patient=patient).values_list(
                "value", flat=True
            )
        )
        self.assertTrue({"91-1111-2222-3333", "jane.doe@sbx"} <= values)
        patient.refresh_from_db()
        self.assertEqual(len(patient.instance_identifiers), len(values))

    def test_one_abha_per_patient_and_one_patient_per_abha(self):
        first, second = self.create_patient(), self.create_patient()
        self.link(self.account, first)
        response = self.link(self.account, second)
        self.assertEqual(response.status_code, 400)
        self.assertIn(str(first.external_id), str(response.json()))

        other = AbhaNumber.objects.create(abha_number="91-4444-5555-6666")
        response = self.link(other, first)
        self.assertEqual(response.status_code, 400)

    def test_link_requires_patient_write_permission(self):
        user = self.create_user()
        self.account.created_by = user
        self.account.save()
        self.client.force_authenticate(user)
        response = self.link(self.account, self.create_patient())
        self.assertEqual(response.status_code, 403)

    @patch(f"{ABHA}.get_card", return_value=(b"PNG", "image/png"))
    def test_card(self, get_card):
        self.account.access_token_expires_at = None
        self.account.refresh_token = None
        self.account.save()
        response = self.client.get(
            reverse("abdm-abha-number-card", args=[self.account.external_id])
        )
        # No live token and nothing to refresh it with: ask for a fresh verification
        self.assertEqual(response.status_code, 400)
        get_card.assert_not_called()

    @patch(f"{ABHA}.get_card", return_value=(b"PNG", "image/png"))
    @patch(f"{ABHA}.refresh_user_token", return_value=TOKENS)
    def test_card_refreshes_an_expired_token(self, refresh, get_card):
        self.account.refresh_token = "r-token"
        self.account.save()
        response = self.client.get(
            reverse("abdm-abha-number-card", args=[self.account.external_id])
        )
        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.content, b"PNG")
        refresh.assert_called_once_with("r-token")
        get_card.assert_called_once_with("x-token", "abha", "card")

    def test_list_by_patient(self):
        patient = self.create_patient()
        self.link(self.account, patient)
        response = self.client.get(
            reverse("abdm-abha-number-list"), {"patient": str(patient.external_id)}
        )
        self.assertEqual(response.json()["count"], 1)
