{"content": "export type AbhaIdentifierType =
  | "aadhaar"
  | "mobile"
  | "abha_number"
  | "abha_address";

export type AbhaOtpSystem = "aadhaar" | "abdm";

export type AbhaGender = "male" | "female" | "transgender" | "non_binary" | "";

export interface AbhaLinkedPatient {
  id: string;
  name: string;
}

export interface AbhaNumber {
  id: string;
  abha_number: string | null;
  abha_address: string | null;
  name: string;
  first_name: string;
  middle_name: string;
  last_name: string;
  gender: AbhaGender;
  date_of_birth: string | null;
  year_of_birth: number | null;
  mobile: string;
  email: string;
  address: string;
  pincode: string;
  state_code: string;
  state_name: string;
  district_code: string;
  district_name: string;
  kyc_verified: boolean;
  status: string;
  profile_photo: string;
  token_kind: "abha" | "phr";
  patient: AbhaLinkedPatient | null;
  created_date: string;
  modified_date: string;
}

export interface AbhaAccount {
  abha_number: string | null;
  abha_address: string | null;
  name: string;
  gender: AbhaGender;
  kyc_verified: boolean;
  status: string;
  profile_photo: string;
  patient: AbhaLinkedPatient | null;
}

export interface AbhaLoginSendOtpRequest {
  identifier: AbhaIdentifierType;
  value: string;
  otp_system: AbhaOtpSystem;
}

export type AbhaLoginSendOtpResponse =
  | { status: "otp_sent"; txn_id: string; message: string }
  | { status: "not_found"; message: string };

export type AbhaLoginVerifyResponse =
  | { status: "found"; abha_number: AbhaNumber }
  | { status: "not_found"; message: string }
  | { status: "select_account"; txn_id: string; accounts: AbhaAccount[] };

export interface AbhaFoundResponse {
  status: "found";
  abha_number: AbhaNumber;
}

export interface AbhaTxnResponse {
  txn_id: string;
  message: string;
}

export interface AbhaEnrolmentConsent {
  code: "abha-enrollment";
  version: string;
  agreed: boolean;
}

export interface AbhaEnrolVerifyResponse extends AbhaTxnResponse {
  is_new: boolean;
  mobile_verification_required: boolean;
  abha_number: AbhaNumber;
}

export interface AbhaErrorDetail {
  type: "abdm_error";
  msg: string;
  code: string | null;
  fields: Record<string, string>;
  request_id: string | null;
}

// Published by ABDM; shown verbatim before an Aadhaar number is asked for
export const ABHA_ENROLMENT_CONSENT = {
  code: "abha-enrollment",
  version: "1.4",
} as const;

export const ABHA_NUMBER_REGEX = /^\d{2}-?\d{4}-?\d{4}-?\d{4}$/;
export const AADHAAR_REGEX = /^\d{12}$/;
export const MOBILE_REGEX = /^[6-9]\d{9}$/;
export const ABHA_ADDRESS_REGEX =
  /^(?!.*\..*\.)(?!.*_.*_)[a-zA-Z][a-zA-Z0-9._]{6,16}[a-zA-Z0-9]$/;
