{"content": "import { TFunction } from "i18next";

import { HTTPError } from "@/Utils/request/types";

/** The message to show on the step the desk is looking at, from an ABDM refusal or a validation error. */
export function getAbhaErrorMessage(error: unknown, t: TFunction): string {
  if (error instanceof HTTPError) {
    const cause = error.cause as
      | { errors?: { msg?: unknown }[]; detail?: unknown }
      | undefined;
    const first = cause?.errors?.[0]?.msg;
    if (typeof first === "string" && first) return first;
    if (typeof cause?.detail === "string" && cause.detail) return cause.detail;
  }
  if (error instanceof Error && error.message) return error.message;
  return t("something_went_wrong");
}

export function formatAbhaNumber(value: string) {
  const digits = value.replace(/\D/g, "").slice(0, 14);
  return [digits.slice(0, 2), digits.slice(2, 6), digits.slice(6, 10)]
    .concat(digits.slice(10))
    .filter(Boolean)
    .join("-");
}
