{"content": "import { REGEXP_ONLY_DIGITS } from "input-otp";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";

const RESEND_WAIT_SECONDS = 60;
const MAX_RESENDS = 2;

interface AbhaOtpInputProps {
  message?: string;
  error?: string;
  isVerifying: boolean;
  isResending: boolean;
  onVerify: (otp: string) => void;
  onResend: () => void;
}

export function AbhaOtpInput({
  message,
  error,
  isVerifying,
  isResending,
  onVerify,
  onResend,
}: AbhaOtpInputProps) {
  const { t } = useTranslation();
  const [otp, setOtp] = useState("");
  const [secondsLeft, setSecondsLeft] = useState(RESEND_WAIT_SECONDS);
  const [resends, setResends] = useState(0);

  useEffect(() => {
    if (secondsLeft <= 0) return;
    const timer = setTimeout(() => setSecondsLeft((s) => s - 1), 1000);
    return () => clearTimeout(timer);
  }, [secondsLeft]);

  const handleResend = () => {
    setResends((r) => r + 1);
    setSecondsLeft(RESEND_WAIT_SECONDS);
    setOtp("");
    onResend();
  };

  return (
    <div className="flex flex-col gap-3">
      {message && (
        <p className="text-sm text-gray-700" role="status">
          {message}
        </p>
      )}
      <InputOTP
        value={otp}
        onChange={setOtp}
        maxLength={6}
        pattern={REGEXP_ONLY_DIGITS}
        autoComplete="one-time-code"
        aria-label={t("abha_enter_otp")}
        autoFocus
      >
        <InputOTPGroup>
          {[...Array(6)].map((_, index) => (
            <InputOTPSlot key={index} index={index} />
          ))}
        </InputOTPGroup>
      </InputOTP>
      {error && (
        <p className="text-sm text-red-600" role="alert">
          {error}
        </p>
      )}
      <div className="flex flex-wrap items-center gap-2">
        <Button
          type="button"
          onClick={() => onVerify(otp)}
          disabled={otp.length !== 6 || isVerifying}
        >
          {isVerifying ? t("verifying") : t("verify_otp")}
        </Button>
        {resends < MAX_RESENDS && (
          <Button
            type="button"
            variant="ghost"
            onClick={handleResend}
            disabled={secondsLeft > 0 || isResending}
          >
            {secondsLeft > 0
              ? t("resend_otp_timer", { time: secondsLeft })
              : t("resend_otp")}
          </Button>
        )}
      </div>
    </div>
  );
}
