{"content": "import { useMutation } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { AbhaOtpInput } from "@/components/Patient/abha/AbhaOtpInput";
import {
  formatAbhaNumber,
  getAbhaErrorMessage,
} from "@/components/Patient/abha/utils";

import {
  AADHAAR_REGEX,
  ABHA_ADDRESS_REGEX,
  ABHA_ENROLMENT_CONSENT,
  ABHA_NUMBER_REGEX,
  AbhaAccount,
  AbhaIdentifierType,
  AbhaNumber,
  AbhaOtpSystem,
  MOBILE_REGEX,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";

/** What the desk already knows about the person in front of it; each fact is asked for once. */
export interface AbhaFacts {
  aadhaar?: string;
  mobile?: string;
  consentAgreed?: boolean;
}

type Step =
  | { name: "identify" }
  | { name: "otp" }
  | { name: "select_account"; accounts: AbhaAccount[] }
  | { name: "not_found"; message: string }
  | { name: "enrol_aadhaar" }
  | { name: "enrol_otp" }
  | { name: "enrol_mobile_otp" }
  | { name: "enrol_address"; suggestions: string[] };

const IDENTIFIERS: AbhaIdentifierType[] = [
  "aadhaar",
  "mobile",
  "abha_number",
  "abha_address",
];

interface AbhaVerificationFlowProps {
  initialFacts?: AbhaFacts;
  onComplete: (abha: AbhaNumber, facts: AbhaFacts) => void;
  onSkip: () => void;
}

export function AbhaVerificationFlow({
  initialFacts,
  onComplete,
  onSkip,
}: AbhaVerificationFlowProps) {
  const { t } = useTranslation();
  const [step, setStepState] = useState<Step>({ name: "identify" });
  const [facts, setFacts] = useState<AbhaFacts>(initialFacts ?? {});
  const [identifier, setIdentifier] = useState<AbhaIdentifierType>("aadhaar");
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem>("abdm");
  const [value, setValue] = useState(initialFacts?.mobile ?? "");
  const [consentAgreed, setConsentAgreed] = useState(
    !!initialFacts?.consentAgreed,
  );
  const [mobile, setMobile] = useState(initialFacts?.mobile ?? "");
  const [address, setAddress] = useState("");
  const [txnId, setTxnId] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const setStep = (next: Step) => {
    setError("");
    setStepState(next);
  };

  // Facts are written once; a later step never silently replaces what was given earlier
  const remember = (next: AbhaFacts) =>
    setFacts((current) => {
      const merged = { ...current };
      for (const [key, val] of Object.entries(next) as [
        keyof AbhaFacts,
        never,
      ][]) {
        if (merged[key] === undefined && val !== undefined) merged[key] = val;
      }
      return merged;
    });

  const onFailure = (e: unknown) => setError(getAbhaErrorMessage(e, t));

  const complete = (abha: AbhaNumber) => onComplete(abha, facts);

  const loginSendOtp = useMutation({
    mutationFn: mutate(abhaApi.login.sendOtp, { silent: true }),
    onSuccess: (res) => {
      if (res.status === "not_found") {
        setStep({ name: "not_found", message: res.message });
        return;
      }
      setTxnId(res.txn_id);
      setMessage(res.message);
      setStep({ name: "otp" });
    },
    onError: onFailure,
  });

  const loginVerifyOtp = useMutation({
    mutationFn: mutate(abhaApi.login.verifyOtp, { silent: true }),
    onSuccess: (res) => {
      if (res.status === "found") return complete(res.abha_number);
      if (res.status === "not_found") {
        setStep({ name: "not_found", message: res.message });
        return;
      }
      setTxnId(res.txn_id);
      setStep({ name: "select_account", accounts: res.accounts });
    },
    onError: onFailure,
  });

  const selectAccount = useMutation({
    mutationFn: mutate(abhaApi.login.selectAccount, { silent: true }),
    onSuccess: (res) => complete(res.abha_number),
    onError: onFailure,
  });

  const enrolSendOtp = useMutation({
    mutationFn: mutate(abhaApi.enrol.sendAadhaarOtp, { silent: true }),
    onSuccess: (res) => {
      setTxnId(res.txn_id);
      setMessage(res.message);
      setStep({ name: "enrol_otp" });
    },
    onError: onFailure,
  });

  const addressSuggestions = useMutation({
    mutationFn: mutate(abhaApi.enrol.addressSuggestions, { silent: true }),
    onSuccess: (res) => {
      setTxnId(res.txn_id);
      setStep({ name: "enrol_address", suggestions: res.suggestions });
    },
    onError: (e) => {
      // Suggestions are a convenience; the desk can still type an address
      setStep({ name: "enrol_address", suggestions: [] });
      onFailure(e);
    },
  });

  const enrolSendMobileOtp = useMutation({
    mutationFn: mutate(abhaApi.enrol.sendMobileOtp, { silent: true }),
    onSuccess: (res) => {
      setTxnId(res.txn_id);
      setMessage(res.message);
      setStep({ name: "enrol_mobile_otp" });
    },
    onError: onFailure,
  });

  const enrolVerifyOtp = useMutation({
    mutationFn: mutate(abhaApi.enrol.verifyAadhaarOtp, { silent: true }),
    onSuccess: (res) => {
      setTxnId(res.txn_id);
      if (!res.is_new) {
        toast.info(res.message || t("abha_already_exists"));
        return complete(res.abha_number);
      }
      if (res.mobile_verification_required) {
        enrolSendMobileOtp.mutate({ txn_id: res.txn_id, mobile });
        return;
      }
      addressSuggestions.mutate({ txn_id: res.txn_id });
    },
    onError: onFailure,
  });

  const enrolVerifyMobileOtp = useMutation({
    mutationFn: mutate(abhaApi.enrol.verifyMobileOtp, { silent: true }),
    onSuccess: (res) => {
      setTxnId(res.txn_id);
      addressSuggestions.mutate({ txn_id: res.txn_id });
    },
    onError: onFailure,
  });

  const setAbhaAddress = useMutation({
    mutationFn: mutate(abhaApi.enrol.setAddress, { silent: true }),
    onSuccess: (res) => complete(res.abha_number),
    onError: onFailure,
  });

  const validateIdentifier = (): string | null => {
    const trimmed = value.trim();
    if (identifier === "aadhaar" && !AADHAAR_REGEX.test(trimmed))
      return t("abha_invalid_aadhaar");
    if (identifier === "mobile" && !MOBILE_REGEX.test(trimmed))
      return t("abha_invalid_mobile");
    if (identifier === "abha_number" && !ABHA_NUMBER_REGEX.test(trimmed))
      return t("abha_invalid_abha_number");
    if (identifier === "abha_address" && !trimmed) return t("field_required");
    if (identifier === "aadhaar" && !consentAgreed)
      return t("abha_consent_required");
    return null;
  };

  const handleSendLoginOtp = () => {
    const problem = validateIdentifier();
    if (problem) return setError(problem);
    const trimmed = value.trim();
    remember({
      aadhaar: identifier === "aadhaar" ? trimmed : undefined,
      mobile: identifier === "mobile" ? trimmed : undefined,
      consentAgreed: identifier === "aadhaar" ? true : undefined,
    });
    if (identifier === "mobile" && !mobile) setMobile(trimmed);
    loginSendOtp.mutate({
      identifier,
      value: trimmed,
      otp_system:
        identifier === "aadhaar"
          ? "aadhaar"
          : identifier === "mobile"
            ? "abdm"
            : otpSystem,
    });
  };

  const handleStartEnrolment = () => {
    if (facts.aadhaar && facts.consentAgreed) {
      enrolSendOtp.mutate({
        aadhaar: facts.aadhaar,
        consent: { ...ABHA_ENROLMENT_CONSENT, agreed: true },
      });
      return;
    }
    setValue("");
    setStep({ name: "enrol_aadhaar" });
  };

  const handleEnrolAadhaar = () => {
    const trimmed = value.trim();
    if (!AADHAAR_REGEX.test(trimmed)) return setError(t("abha_invalid_aadhaar"));
    if (!consentAgreed) return setError(t("abha_consent_required"));
    remember({ aadhaar: trimmed, consentAgreed: true });
    enrolSendOtp.mutate({
      aadhaar: trimmed,
      consent: { ...ABHA_ENROLMENT_CONSENT, agreed: true },
    });
  };

  const handleEnrolVerify = (otp: string) => {
    if (!MOBILE_REGEX.test(mobile)) return setError(t("abha_invalid_mobile"));
    remember({ mobile });
    enrolVerifyOtp.mutate({ txn_id: txnId, otp, mobile });
  };

  const handleSetAddress = (chosen: string) => {
    const handle = chosen.trim().split("@")[0];
    if (/^\d{10}$/.test(handle) || !ABHA_ADDRESS_REGEX.test(handle))
      return setError(t("abha_address_rules"));
    setAbhaAddress.mutate({ txn_id: txnId, abha_address: handle });
  };

  const restart = () => {
    setTxnId("");
    setMessage("");
    setStep({ name: "identify" });
  };

  const consent = (
    <div className="flex flex-col gap-2 rounded-md border border-gray-200 bg-gray-50 p-3">
      <p className="text-sm font-semibold">{t("abha_consent_title")}</p>
      <div className="max-h-40 overflow-y-auto text-xs text-gray-700 whitespace-pre-line">
        {t("abha_consent_text")}
      </div>
      <div className="flex items-start gap-2">
        <Checkbox
          id="abha-consent"
          checked={consentAgreed}
          onCheckedChange={(checked) => setConsentAgreed(checked === true)}
        />
        <Label htmlFor="abha-consent" className="text-sm leading-snug">
          {t("abha_consent_agree")}
        </Label>
      </div>
    </div>
  );

  const errorMessage = error && (
    <p className="text-sm text-red-600" role="alert">
      {error}
    </p>
  );

  const skipButton = (
    <Button type="button" variant="outline" onClick={onSkip}>
      {t("abha_continue_without")}
    </Button>
  );

  return (
    <div className="flex flex-col gap-4" aria-live="polite">
      {step.name === "identify" && (
        <>
          <Tabs
            value={identifier}
            onValueChange={(v) => {
              setIdentifier(v as AbhaIdentifierType);
              setValue(v === "mobile" ? (facts.mobile ?? "") : "");
              setError("");
            }}
          >
            <TabsList className="flex flex-wrap h-auto">
              {IDENTIFIERS.map((id) => (
                <TabsTrigger key={id} value={id}>
                  {t(`abha_identifier__${id}`)}
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>
          {identifier === "aadhaar" && consent}
          <div className="flex flex-col gap-1">
            <Label htmlFor="abha-identifier">
              {t(`abha_identifier__${identifier}`)}
            </Label>
            <Input
              id="abha-identifier"
              value={value}
              inputMode={identifier === "abha_address" ? "text" : "numeric"}
              autoComplete="off"
              placeholder={t(`abha_identifier_placeholder__${identifier}`)}
              onChange={(e) =>
                setValue(
                  identifier === "abha_number"
                    ? formatAbhaNumber(e.target.value)
                    : e.target.value,
                )
              }
            />
          </div>
          {(identifier === "abha_number" || identifier === "abha_address") && (
            <RadioGroup
              value={otpSystem}
              onValueChange={(v) => setOtpSystem(v as AbhaOtpSystem)}
              className="flex gap-4"
              aria-label={t("abha_verify_with")}
            >
              {(["abdm", "aadhaar"] as const).map((system) => (
                <div key={system} className="flex items-center gap-2">
                  <RadioGroupItem value={system} id={`abha-otp-${system}`} />
                  <Label htmlFor={`abha-otp-${system}`}>
                    {t(`abha_otp_system__${system}`)}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          )}
          {errorMessage}
          <div className="flex flex-wrap gap-2">
            <Button
              type="button"
              onClick={handleSendLoginOtp}
              disabled={loginSendOtp.isPending}
            >
              {loginSendOtp.isPending ? t("sending") : t("send_otp")}
            </Button>
            {skipButton}
          </div>
        </>
      )}

      {step.name === "otp" && (
        <AbhaOtpInput
          message={message}
          error={error}
          isVerifying={loginVerifyOtp.isPending}
          isResending={loginSendOtp.isPending}
          onVerify={(otp) => loginVerifyOtp.mutate({ txn_id: txnId, otp })}
          onResend={handleSendLoginOtp}
        />
      )}

      {step.name === "select_account" && (
        <div className="flex flex-col gap-2">
          <p className="text-sm text-gray-700">{t("abha_select_account")}</p>
          {step.accounts.map((account) => (
            <button
              key={account.abha_number ?? account.abha_address}
              type="button"
              className="flex items-center gap-3 rounded-md border border-gray-200 p-3 text-left hover:bg-gray-50 focus-visible:ring-1 focus-visible:outline-hidden disabled:opacity-50"
              disabled={selectAccount.isPending || !account.abha_number}
              onClick={() =>
                account.abha_number &&
                selectAccount.mutate({
                  txn_id: txnId,
                  abha_number: account.abha_number,
                })
              }
            >
              {account.profile_photo ? (
                <img
                  src={`data:image/jpeg;base64,${account.profile_photo}`}
                  alt=""
                  className="size-12 rounded-full object-cover"
                />
              ) : (
                <div className="size-12 rounded-full bg-gray-200" />
              )}
              <div className="flex flex-col">
                <span className="font-medium">{account.name}</span>
                <span className="text-sm text-gray-600">
                  {account.abha_number}
                  {account.abha_address && ` · ${account.abha_address}`}
                </span>
                {account.patient && (
                  <span className="text-xs text-amber-700">
                    {t("abha_already_linked_to", {
                      name: account.patient.name,
                      id: account.patient.id,
                    })}
                  </span>
                )}
              </div>
            </button>
          ))}
          {errorMessage}
        </div>
      )}

      {step.name === "not_found" && (
        <div className="flex flex-col gap-3">
          <p className="text-sm text-gray-700" role="status">
            {step.message || t("abha_not_found")}
          </p>
          {errorMessage}
          <div className="flex flex-wrap gap-2">
            <Button
              type="button"
              onClick={handleStartEnrolment}
              disabled={enrolSendOtp.isPending}
            >
              {facts.aadhaar
                ? t("abha_create_with_this_aadhaar")
                : t("abha_create_with_aadhaar")}
            </Button>
            {skipButton}
          </div>
        </div>
      )}

      {step.name === "enrol_aadhaar" && (
        <>
          {consent}
          <div className="flex flex-col gap-1">
            <Label htmlFor="abha-aadhaar">{t("aadhaar_number")}</Label>
            <Input
              id="abha-aadhaar"
              value={value}
              inputMode="numeric"
              autoComplete="off"
              onChange={(e) => setValue(e.target.value)}
            />
          </div>
          {errorMessage}
          <div className="flex flex-wrap gap-2">
            <Button
              type="button"
              onClick={handleEnrolAadhaar}
              disabled={enrolSendOtp.isPending}
            >
              {t("send_otp")}
            </Button>
            {skipButton}
          </div>
        </>
      )}

      {step.name === "enrol_otp" && (
        <>
          <div className="flex flex-col gap-1">
            <Label htmlFor="abha-mobile">{t("abha_communication_mobile")}</Label>
            <Input
              id="abha-mobile"
              value={mobile}
              inputMode="numeric"
              onChange={(e) => setMobile(e.target.value.trim())}
            />
            {facts.mobile && mobile === facts.mobile && (
              <span className="text-xs text-gray-500">
                {t("abha_value_from_earlier")}
              </span>
            )}
          </div>
          <AbhaOtpInput
            message={message}
            error={error}
            isVerifying={
              enrolVerifyOtp.isPending ||
              enrolSendMobileOtp.isPending ||
              addressSuggestions.isPending
            }
            isResending={enrolSendOtp.isPending}
            onVerify={handleEnrolVerify}
            onResend={handleStartEnrolment}
          />
        </>
      )}

      {step.name === "enrol_mobile_otp" && (
        <AbhaOtpInput
          message={message}
          error={error}
          isVerifying={
            enrolVerifyMobileOtp.isPending || addressSuggestions.isPending
          }
          isResending={enrolSendMobileOtp.isPending}
          onVerify={(otp) => enrolVerifyMobileOtp.mutate({ txn_id: txnId, otp })}
          onResend={() => enrolSendMobileOtp.mutate({ txn_id: txnId, mobile })}
        />
      )}

      {step.name === "enrol_address" && (
        <div className="flex flex-col gap-3">
          <p className="text-sm text-gray-700">{t("abha_choose_address")}</p>
          {step.suggestions.length > 0 && (
            <div className="flex flex-wrap gap-2">
              {step.suggestions.map((suggestion) => (
                <Button
                  key={suggestion}
                  type="button"
                  variant={address === suggestion ? "primary" : "outline"}
                  size="sm"
                  onClick={() => setAddress(suggestion)}
                >
                  {suggestion}
                </Button>
              ))}
            </div>
          )}
          <div className="flex flex-col gap-1">
            <Label htmlFor="abha-address">{t("abha_address")}</Label>
            <Input
              id="abha-address"
              value={address}
              autoComplete="off"
              onChange={(e) => setAddress(e.target.value)}
            />
            <span className="text-xs text-gray-500">
              {t("abha_address_rules")}
            </span>
          </div>
          {errorMessage}
          <Button
            type="button"
            onClick={() => handleSetAddress(address)}
            disabled={!address || setAbhaAddress.isPending}
          >
            {t("abha_create_address")}
          </Button>
        </div>
      )}

      {step.name !== "identify" && (
        <Button
          type="button"
          variant="link"
          className="self-start px-0"
          onClick={restart}
        >
          {t("abha_start_over")}
        </Button>
      )}
    </div>
  );
}
