{"content": "import { useQuery } from "@tanstack/react-query";
import { DownloadIcon } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import Loading from "@/components/Common/Loading";
import { getAbhaErrorMessage } from "@/components/Patient/abha/utils";

import { AbhaNumber } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import query from "@/Utils/request/query";

interface AbhaCardDialogProps {
  abha: AbhaNumber;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function AbhaCardDialog({
  abha,
  open,
  onOpenChange,
}: AbhaCardDialogProps) {
  const { t } = useTranslation();
  const [isDownloading, setIsDownloading] = useState(false);

  const card = useQuery({
    queryKey: ["abha_card", abha.id],
    queryFn: query(abhaApi.abhaNumber.card, {
      pathParams: { id: abha.id },
      queryParams: { kind: "card" },
      silent: true,
    }),
    enabled: open,
    retry: false,
  });

  const cardUrl = useMemo(
    () => (card.data ? URL.createObjectURL(card.data) : undefined),
    [card.data],
  );
  useEffect(() => () => cardUrl && URL.revokeObjectURL(cardUrl), [cardUrl]);

  const handleDownload = async () => {
    setIsDownloading(true);
    try {
      const pdf = await query(abhaApi.abhaNumber.card, {
        pathParams: { id: abha.id },
        queryParams: { kind: abha.token_kind === "phr" ? "card" : "pdf" },
      })({ signal: new AbortController().signal });
      const url = URL.createObjectURL(pdf);
      const link = document.createElement("a");
      link.href = url;
      link.download = `abha-${abha.abha_number ?? abha.abha_address}`;
      link.click();
      URL.revokeObjectURL(url);
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>{t("abha_card")}</DialogTitle>
          <DialogDescription>
            {abha.abha_number} {abha.abha_address && `· ${abha.abha_address}`}
          </DialogDescription>
        </DialogHeader>
        {card.isLoading && <Loading />}
        {card.isError && (
          <p className="text-sm text-red-600" role="alert">
            {getAbhaErrorMessage(card.error, t)}
          </p>
        )}
        {cardUrl && (
          <img src={cardUrl} alt={t("abha_card")} className="w-full rounded" />
        )}
        <Button
          type="button"
          variant="outline"
          onClick={handleDownload}
          disabled={isDownloading || card.isError}
          className="self-end"
        >
          <DownloadIcon />
          {t("download")}
        </Button>
      </DialogContent>
    </Dialog>
  );
}
