{"content": "import { Link } from "raviger";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import { AbhaCardDialog } from "@/components/Patient/abha/AbhaCardDialog";
import {
  AbhaFacts,
  AbhaVerificationFlow,
} from "@/components/Patient/abha/AbhaVerificationFlow";

import { AbhaNumber } from "@/types/abdm/abha";

interface AbhaRegistrationStepProps {
  abha: AbhaNumber | null;
  facilityId?: string;
  initialFacts?: AbhaFacts;
  filledFields: string[];
  onVerified: (abha: AbhaNumber, facts: AbhaFacts) => void;
  onRemove: () => void;
}

/** The ABHA step that comes before the registration form and fills it; registration never waits on it. */
export function AbhaRegistrationStep({
  abha,
  facilityId,
  initialFacts,
  filledFields,
  onVerified,
  onRemove,
}: AbhaRegistrationStepProps) {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [isCardOpen, setIsCardOpen] = useState(false);

  return (
    <section
      className="bg-white flex flex-col gap-4 p-6 shadow rounded-md"
      aria-labelledby="abha-step-title"
    >
      <div className="flex flex-col">
        <h2 id="abha-step-title" className="font-semibold">
          {t("abha_step_title")}
        </h2>
        <span className="text-sm text-gray-600">
          {t("abha_step_description")}
        </span>
      </div>

      {!abha && !isOpen && (
        <Button
          type="button"
          variant="outline_primary"
          className="self-start"
          onClick={() => setIsOpen(true)}
        >
          {t("abha_find_or_create")}
        </Button>
      )}

      {!abha && isOpen && (
        <AbhaVerificationFlow
          initialFacts={initialFacts}
          onComplete={(verified, facts) => {
            setIsOpen(false);
            onVerified(verified, facts);
          }}
          onSkip={() => setIsOpen(false)}
        />
      )}

      {abha && (
        <div className="flex flex-col gap-3">
          <div className="flex items-center gap-3">
            {abha.profile_photo ? (
              <img
                src={`data:image/jpeg;base64,${abha.profile_photo}`}
                alt=""
                className="size-14 rounded-full object-cover"
              />
            ) : (
              <div className="size-14 rounded-full bg-gray-200" />
            )}
            <div className="flex flex-col">
              <span className="font-medium">{abha.name}</span>
              <span className="text-sm text-gray-700">
                {t("abha_number")}: {abha.abha_number ?? "-"}
              </span>
              <span className="text-sm text-gray-700">
                {t("abha_address")}: {abha.abha_address ?? "-"}
              </span>
            </div>
            {abha.kyc_verified && (
              <Badge variant="green" className="ml-auto">
                {t("abha_kyc_verified")}
              </Badge>
            )}
          </div>

          {abha.patient ? (
            <Alert variant="destructive">
              <AlertTitle>{t("abha_already_linked")}</AlertTitle>
              <AlertDescription>
                {t("abha_already_linked_to", {
                  name: abha.patient.name,
                  id: abha.patient.id,
                })}{" "}
                {facilityId && (
                  <Link
                    href={`/facility/${facilityId}/patient/${abha.patient.id}`}
                    className="underline"
                  >
                    {t("abha_open_existing_patient")}
                  </Link>
                )}
              </AlertDescription>
            </Alert>
          ) : (
            filledFields.length > 0 && (
              <p className="text-sm text-gray-600" role="status">
                {t("abha_filled_from_profile", {
                  fields: filledFields.map((f) => t(f)).join(", "),
                })}
              </p>
            )
          )}

          <div className="flex flex-wrap gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsCardOpen(true)}
            >
              {t("abha_view_card")}
            </Button>
            <Button type="button" variant="ghost" onClick={onRemove}>
              {t("abha_remove")}
            </Button>
          </div>
          <AbhaCardDialog
            abha={abha}
            open={isCardOpen}
            onOpenChange={setIsCardOpen}
          />
        </div>
      )}
    </section>
  );
}
