{"content": "import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import { AbhaCardDialog } from "@/components/Patient/abha/AbhaCardDialog";
import { AbhaVerificationFlow } from "@/components/Patient/abha/AbhaVerificationFlow";

import { PatientRead } from "@/types/emr/patient/patient";
import { AbhaNumber } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

interface PatientAbhaPanelProps {
  patient: PatientRead;
}

/** The patient's ABHA on their record, with the offer to verify or create one when it is missing. */
export function PatientAbhaPanel({ patient }: PatientAbhaPanelProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [isLinkOpen, setIsLinkOpen] = useState(false);
  const [isCardOpen, setIsCardOpen] = useState(false);

  const queryKey = ["abha_number", "patient", patient.id];
  const { data, isLoading } = useQuery({
    queryKey,
    queryFn: query(abhaApi.abhaNumber.list, {
      queryParams: { patient: patient.id },
      silent: true,
    }),
  });
  const abha = data?.results[0];

  const { mutate: linkPatient, isPending: isLinking } = useMutation({
    mutationFn: (verified: AbhaNumber) =>
      mutate(abhaApi.abhaNumber.linkPatient, {
        pathParams: { id: verified.id },
      })({ patient: patient.id }),
    onSuccess: () => {
      setIsLinkOpen(false);
      queryClient.invalidateQueries({ queryKey });
      queryClient.invalidateQueries({ queryKey: ["patient", patient.id] });
    },
  });

  if (isLoading) return null;

  return (
    <div className="mt-4 rounded-md border border-blue-400 bg-blue-50 p-5 flex flex-col gap-3">
      {abha ? (
        <>
          <div className="grid grid-cols-1 gap-x-4 gap-y-2 md:grid-cols-2">
            {[
              { label: t("abha_number"), value: abha.abha_number ?? "-" },
              { label: t("abha_address"), value: abha.abha_address ?? "-" },
            ].map((info) => (
              <div key={info.label}>
                <p className="text-sm text-gray-600">{info.label}:</p>
                <p className="text-sm font-semibold text-gray-900">
                  {info.value}
                </p>
              </div>
            ))}
          </div>
          <Button
            type="button"
            variant="outline"
            className="self-start"
            onClick={() => setIsCardOpen(true)}
          >
            {t("abha_view_card")}
          </Button>
          <AbhaCardDialog
            abha={abha}
            open={isCardOpen}
            onOpenChange={setIsCardOpen}
          />
        </>
      ) : (
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm text-gray-700">{t("abha_not_linked")}</p>
          <Button
            type="button"
            variant="outline_primary"
            onClick={() => setIsLinkOpen(true)}
          >
            {t("abha_find_or_create")}
          </Button>
        </div>
      )}

      <Dialog open={isLinkOpen} onOpenChange={setIsLinkOpen}>
        <DialogContent className="max-w-xl">
          <DialogHeader>
            <DialogTitle>{t("abha_step_title")}</DialogTitle>
          </DialogHeader>
          {isLinking ? (
            <p className="text-sm text-gray-600">{t("loading")}</p>
          ) : (
            <AbhaVerificationFlow
              onComplete={(verified) => linkPatient(verified)}
              onSkip={() => setIsLinkOpen(false)}
            />
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}
